	if snapshot != nil && len(snapshot.InjectionScopes) > 0 {
		opts = append(opts, memoryloop.WithInjectionScopes(snapshot.InjectionScopes))
	}
	if settingsValue, err := LoadEntireSettings(ctx); err == nil {
